<?php
declare(strict_types=1);
require_once __DIR__.'/christmas-advent-2026.php';
const CHRISTMAS26_PAYOUT_GATE='NARRRFS_CHRISTMAS_ADVENT_2026_PAYOUT_ENABLED';const CHRISTMAS26_POLICY_VERSION_ENV='NARRRFS_CHRISTMAS_ADVENT_2026_POLICY_VERSION';const CHRISTMAS26_POLICY_VERSION='christmas_advent_2026_v1';const CHRISTMAS26_CSRF_SESSION_KEY='christmas_advent_2026_claim_csrf';
function christmas26_claim_payout_is_enabled(?string $g,?string $v):bool{return $g==='1'&&$v===CHRISTMAS26_POLICY_VERSION;}
function christmas26_claim_origin_is_allowed(array $s):bool{return in_array(strtolower(trim((string)($s['HTTP_ORIGIN']??''))),['https://narrrfs.world','http://localhost','http://127.0.0.1'],true);}
function christmas26_claim_issue_csrf(array &$s):string{$t=bin2hex(random_bytes(32));$s[CHRISTMAS26_CSRF_SESSION_KEY]=['token'=>$t,'created_at'=>time()];return $t;}
function christmas26_claim_csrf_is_valid(array &$s,?string $t):bool{$e=$s[CHRISTMAS26_CSRF_SESSION_KEY]??null;unset($s[CHRISTMAS26_CSRF_SESSION_KEY]);return is_array($e)&&is_string($t)&&is_string($e['token']??null)&&is_int($e['created_at']??null)&&time()-$e['created_at']>=0&&time()-$e['created_at']<=300&&hash_equals($e['token'],$t);}
function christmas26_claim_policy_fingerprint(array $p):string{$v=['event'=>CHRISTMAS26_EVENT_KEY,'start'=>'2026-12-01','end'=>'2026-12-24','version'=>$p['version']??null,'rewards'=>$p['rewards']??null,'daily_caps'=>$p['daily_caps']??null,'per_user_cap'=>$p['per_user_cap']??null,'event_cap'=>$p['event_cap']??null];return hash('sha256',json_encode($v,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE));}
function christmas26_claim_policy_reason(array $p):string{return CHRISTMAS26_EVENT_KEY.'|'.$p['version'].'|'.christmas26_claim_policy_fingerprint($p);}
function christmas26_claim_policy_is_valid(array $p):bool{if(($p['version']??null)!==CHRISTMAS26_POLICY_VERSION||!is_string($p['fingerprint']??null)||!is_int($p['per_user_cap']??null)||!is_int($p['event_cap']??null))return false;for($d=1;$d<=24;$d++)if(!is_int($p['rewards'][$d]??null)||$p['rewards'][$d]<=0||!is_int($p['daily_caps'][$d]??null)||$p['daily_caps'][$d]<=0)return false;return hash_equals(christmas26_claim_policy_fingerprint($p),$p['fingerprint']);}
function christmas26_claim_replay_receipt(SQLite3 $db,string $u,string $date,array $p): ?array{
 $q=$db->prepare('SELECT c.claim_id,c.reward_dspoinc,c.claimed_at,c.actor_user_id,s.user_id su,s.game,s.source,s.score,a.user_id au,a.admin_id,a.amount,a.action,a.reason FROM tbl_christmas_advent_2026_claims c LEFT JOIN tbl_user_scores s ON s.id=c.score_id LEFT JOIN tbl_score_adjustments a ON a.id=c.adjustment_id WHERE c.event_key=:e AND c.user_id=:u AND c.calendar_date=:d');if(!$q instanceof SQLite3Stmt)throw new RuntimeException('claim_unavailable');$q->bindValue(':e',CHRISTMAS26_EVENT_KEY);$q->bindValue(':u',$u);$q->bindValue(':d',$date);$z=$q->execute();$r=$z instanceof SQLite3Result?$z->fetchArray(SQLITE3_ASSOC):false;if($r===false)return null;if($z->fetchArray(SQLITE3_ASSOC)!==false||(string)$r['actor_user_id']!==$u||(string)$r['su']!==$u||(string)$r['game']!==CHRISTMAS26_EVENT_KEY||(string)$r['source']!==CHRISTMAS26_EVENT_KEY||(int)$r['score']!==(int)$r['reward_dspoinc']||(string)$r['au']!==$u||(string)$r['admin_id']!==$u||(int)$r['amount']!==(int)$r['reward_dspoinc']||(string)$r['action']!=='add'||!hash_equals(christmas26_claim_policy_reason($p),(string)$r['reason']))throw new RuntimeException('claim_unavailable');return ['claim_id'=>(int)$r['claim_id'],'reward_dspoinc'=>(int)$r['reward_dspoinc'],'claimed_at'=>(string)$r['claimed_at'],'calendar_date'=>$date,'replayed'=>true];
}
function christmas26_claim_execute(SQLite3 $db,string $u,DateTimeImmutable $now,array $p,?callable $hook=null):array{
 if(!preg_match('/^\d{17,20}$/',$u)||!christmas26_claim_policy_is_valid($p)||christmas26_event_state($now)!=='active')throw new RuntimeException('claim_unavailable');
 $v=christmas26_vienna_time($now);$d=(int)$v->format('j');$date=$v->format('Y-m-d');$tx=false;
 try{if(!$db->exec('PRAGMA foreign_keys=ON')||(int)$db->querySingle('PRAGMA foreign_keys')!==1||christmas26_claims_schema_error($db)!==null||!$db->exec('BEGIN IMMEDIATE'))throw new RuntimeException('claim_unavailable');$tx=true;$q="'".SQLite3::escapeString($u)."'";if(!$db->querySingle("SELECT 1 FROM tbl_users WHERE discord_id=$q"))throw new RuntimeException('claim_unavailable');
 $rows=christmas26_verified_claims($db,$u);if(isset($rows[$d])){$r=christmas26_claim_replay_receipt($db,$u,$date,$p);if($r===null)throw new RuntimeException('claim_unavailable');$db->exec('COMMIT');$tx=false;return $r;}
 $x=$db->querySingle("SELECT COALESCE(SUM(reward_dspoinc),0) e,COALESCE(SUM(CASE WHEN calendar_date='$date' THEN reward_dspoinc ELSE 0 END),0) d,COALESCE(SUM(CASE WHEN user_id=$q THEN reward_dspoinc ELSE 0 END),0) u FROM tbl_christmas_advent_2026_claims WHERE event_key='".CHRISTMAS26_EVENT_KEY."'",true);$a=$p['rewards'][$d];if(!is_array($x)||$x['e']+$a>$p['event_cap']||$x['d']+$a>$p['daily_caps'][$d]||$x['u']+$a>$p['per_user_cap'])throw new RuntimeException('budget_exhausted');
 $st=$db->prepare("INSERT INTO tbl_user_scores(user_id,game,score,source)VALUES(:u,:g,:a,:g)");$st->bindValue(':u',$u);$st->bindValue(':g',CHRISTMAS26_EVENT_KEY);$st->bindValue(':a',$a,SQLITE3_INTEGER);$st->execute();$sid=$db->lastInsertRowID();$hook&&$hook('after_score',$db);
 $st=$db->prepare("INSERT INTO tbl_score_adjustments(user_id,admin_id,amount,action,reason)VALUES(:u,:u,:a,'add',:r)");$st->bindValue(':u',$u);$st->bindValue(':a',$a,SQLITE3_INTEGER);$st->bindValue(':r',christmas26_claim_policy_reason($p));$st->execute();$aid=$db->lastInsertRowID();$hook&&$hook('after_audit',$db);
 $st=$db->prepare("INSERT INTO tbl_christmas_advent_2026_claims(event_key,user_id,calendar_date,day_number,reward_dspoinc,actor_user_id,score_id,adjustment_id)VALUES(:e,:u,:dt,:d,:a,:u,:s,:i)");foreach([':e'=>CHRISTMAS26_EVENT_KEY,':u'=>$u,':dt'=>$date,':d'=>$d,':a'=>$a,':s'=>$sid,':i'=>$aid]as$k=>$z)$st->bindValue($k,$z,is_int($z)?SQLITE3_INTEGER:SQLITE3_TEXT);$st->execute();$id=$db->lastInsertRowID();$hook&&$hook('after_marker',$db);if(!isset(christmas26_verified_claims($db,$u)[$d]))throw new RuntimeException('claim_unavailable');$at=(string)$db->querySingle("SELECT claimed_at FROM tbl_christmas_advent_2026_claims WHERE claim_id=$id");$db->exec('COMMIT');$tx=false;return ['claim_id'=>$id,'calendar_date'=>$date,'reward_dspoinc'=>$a,'claimed_at'=>$at,'replayed'=>false];
 }catch(Throwable $e){if($tx)$db->exec('ROLLBACK');if($e->getMessage()==='budget_exhausted')throw $e;throw new RuntimeException('claim_unavailable');}}